// Lädt einmal, prüft Überlauf, macht Viewport-Screenshots in Schritten.
// aktion: js-Code, der vor den Screenshots im Browser ausgeführt wird
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [pfad, breite = "1440", name = "x", schritt = "0", aktion = ""] = process.argv.slice(2);
const b = await chromium.launch();
const h = +breite < 600 ? 844 : 900;
const p = await b.newPage({ viewport: { width: +breite, height: h }, deviceScaleFactor: 1 });
const fehler = [];
p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 300)));
const r = await p.goto("http://localhost:3100" + pfad, { waitUntil: "load", timeout: 240000 });
await p.waitForTimeout(2500);
try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1500 }); } catch {}
await p.evaluate(() => document.querySelectorAll(".ov-reveal").forEach((e) => e.classList.add("is-visible")));
if (aktion) { await p.evaluate(aktion); await p.waitForTimeout(1200); }
const info = await p.evaluate(() => {
  const w = document.documentElement.clientWidth;
  const breit = [...document.querySelectorAll("body *")].filter((e) => { const r = e.getBoundingClientRect(); return r.right > w + 1 && r.width > 0 && getComputedStyle(e).position !== "fixed"; }).slice(0, 8).map((e) => e.tagName + "." + String(e.className).slice(0, 60));
  return { sw: document.documentElement.scrollWidth, w, hoehe: document.body.scrollHeight, breit };
});
const out = (n) => fileURLToPath(new URL("./shots/" + n, import.meta.url));
const s = +schritt;
if (s > 0) {
  let i = 0;
  for (let y = 0; y < info.hoehe; y += s, i++) {
    await p.evaluate((y) => window.scrollTo(0, y), y);
    await p.waitForTimeout(350);
    await p.screenshot({ path: out(`${name}_${breite}_${i}.png`) });
  }
  console.log(r.status(), name, "Teile", i);
} else {
  await p.screenshot({ path: out(`${name}_${breite}.png`) });
  console.log(r.status(), name);
}
console.log("Überlauf:", info.sw > info.w ? `JA ${info.sw}>${info.w} ${info.breit.join(" | ")}` : "nein", "Höhe", info.hoehe);
if (fehler.length) console.log(fehler.join("\n"));
await b.close();
EOF
